      `,cards:[{label:"浅いお堀の役割",line1:"SiN→SiO₂→Siを連続ドライエッチ",line2:"隣り合うトランジスタを完全絶縁",accent:"#0284c7"},{label:"主要装置・形状",line1:"TEL / ラムリサーチ エッチャー",line2:"深さ250〜350nm・角度80〜85°",accent:"#4f46e5"},{label:"写真への影響",line1:"角が尖ると電界集中で暗部ノイズ",line2:"滑らかな傾斜がノイズレスの基本",accent:"#e11d48"}]}),fab4_p037_sti_liner_hdp_fill:()=>a({badge:"F4-08",stepTag:"P03-037〜040 [標準]",title:"STIライナー熱酸化（1,000℃角丸め）＆HDP/FCVDガラス完全充填",analogy:"炎で角を丸く治療し、流動ガラスを気泡（ボイド）ゼロでお堀に流し込む",accent:"#0ea5e9",accentSoft:"#f0f9ff",body:`
