      `,cards:[{label:"極薄10nmの効能",line1:"ALD/LPCVDでゲート側壁に10nm膜",line2:"次工程の注入位置をわずかに離隔",accent:"#0891b2"},{label:"高感度ノイズの物理",line1:"変換効率 CG ＝ q / C_FD",line2:"TG-FD重なり容量を減らし高感度化",accent:"#0284c7"},{label:"ブロック3-E開幕",line1:"P03-297〜298(非露光2工程)",line2:"下階テラスのLDD・P+蓋へ接続",accent:"#7c3aed"}]}),fab4_m20_pixel_nldd_fd:()=>a({badge:"F4-35",stepTag:"Mask #20 / 低リークFD",title:"【Mask #20】画素側NLDD＆低リークFD注入（星空撮影を守る計量カップ）",analogy:"電子を電圧へ変える計量カップ(FD)の底を優しい濃度のリンで作り、長時間露光の漏れを止める",accent:"#2563eb",accentSoft:"#eff6ff",body:`
