      `,cards:[{label:"原子を目覚めさせる閃光",line1:"約1,000〜1,050℃へ約1秒前後で急加熱",line2:"打込んだ原子をSi結晶格子へ定着",accent:"#ea580c"},{label:"主要装置・技術",line1:"AMAT / SCREEN ハロゲンランプRTA",line2:"さらに高速なレーザーアニールも併用",accent:"#0284c7"},{label:"写真への影響",line1:"長焼きすると数十nmのP+蓋がにじみ",line2:"青色感度と転送効率が大幅に悪化",accent:"#e11d48"}]}),fab4_m25_salicide_block_sab:()=>a({badge:"F4-42",stepTag:"★Mask #25 CIS秘技SAB",title:"【Mask #25】シリサイドブロック（SAB：画素金属保護・CPUとの差！）",analogy:"周辺回路は金属化で爆速にしつつ、光を受ける画素の上だけはガラスのフタで金属を完全遮断！",accent:"#059669",accentSoft:"#ecfdf5",body:`
