      `,cards:[{label:"なぜ画素だけ金属NG？",line1:"Co/Ni金属が微量でもPDへ染みると",line2:"壊滅的な暗電流・白キズ地獄に！",accent:"#059669"},{label:"最終Mask #25の仕組み",line1:"全面に30〜50nm保護膜(SAB)を成膜",line2:"周辺回路の上だけ開けて画素を封印",accent:"#0284c7"},{label:"CPU工場との決定的差",line1:"CPUは全素子をシリサイド化",line2:"CISは「高速周辺×清浄画素」を両立",accent:"#e11d48"}]}),fab4_p379_salicide_cosi_nisi:()=>a({badge:"F4-43",stepTag:"P03-379 NiSi/CoSi₂",title:"自己整合シリサイド（サリサイド：CoSi₂ / NiSi）形成＆未反応金属除去",analogy:"全面に金属を乗せて焼くと開口した周辺だけ合金化！ 画素上の未反応金属は綺麗に洗い流す",accent:"#0284c7",accentSoft:"#e0f2fe",body:`
