      `,cards:[{label:"極細の釘穴加工",line1:"穴径80〜120nm × 深さ400〜600nm",line2:"高アスペクト比で垂直に掘り抜く",accent:"#2563eb"},{label:"2段階エッチの妙技",line1:"浅いゲートと深いFDをCESLで一旦止め",line2:"低ダメージガスで優しく最終開孔",accent:"#059669"},{label:"写真への影響",line1:"FDシリコンへのプラズマ傷を防ぎ",line2:"夜景の白キズ(ホットピクセル)根絶",accent:"#e11d48"}]}),fab5_p019_titin_w_cvd_nail:()=>a({badge:"F5-07",stepTag:"P04-019〜020 W釘",title:"Ti/TiN鎧＋タングステン（W）CVD釘埋め込み（銅の毒を遮断！）",analogy:"銅はシリコンの天敵！ 1階の釘には拡散しない安全なタングステン（W）を使う",accent:"#475569",accentSoft:"#f1f5f9",body:`
