        `,cards:[{label:"なにをする部品？",line1:"アイセンサー表面を覆う黒い赤外窓と",line2:"発光・受光の間を仕切る遮光隔壁"},{label:"スゴい工夫・秘密",line1:"940nm赤外線だけ90%通す特殊樹脂＋",line2:"2色成形の遮光壁で横漏れクロストーク0"},{label:"撮影でどう嬉しい？",line1:"直射日光の下でも「顔の接近」だけを",line2:"正確に検知しEVF/液晶をストレスなく切替"}]});case"evf_oem_eye_sensor_cushions":return T({badge:"E34",title:"Sony純正 アイセンサー4層保護サンド（WP/RET/GND/ES-1008）",analogy:"汗と雨と静電気からセンサーを守る「4層重ねの防水＆アース座布団」",accent:"#ea580c",accentSoft:"#fff7ed",body:`
