        `,cards:[{label:"どんな部品？",line1:"0.25mm厚SUS304プレス絞り成形の",line2:"BLU金属バックトレー＆ESR粘着層"},{label:"スゴい工夫",line1:"平面度0.08mm未満の剛性保持と",line2:"LED放熱・EMI遮蔽を1枚で兼任"},{label:"撮影メリット",line1:"長年の振動でも光学シートがズレず",line2:"画面中央の輝度ムラやノイズを防止"}]});case"lcd_led_mcpcb_ntc":return m({badge:"D82",title:"LEDバー高熱伝導アルミMCPCB・バランス抵抗＆NTCサーミスタ",analogy:"真夏1,000nitのLED発熱をアルミ板で逃がしつつ中央の「温度計チップ」で守る仕組み",accent:"#d97706",accentSoft:"#fef3c7",body:`
