        `,cards:[{label:"高減衰ゲル制振",line1:"損失係数 tan δ > 0.6 の粘弾性ゲル",line2:"震度7の揺れを熱に変えて機材保護"},{label:"水平出しと気密",line1:"4隅M10ネジで±12mmの精密調整",line2:"箱の歪みを消して扉パッキン最適化"},{label:"壁面転倒防止",line1:"背面上部SUS304耐震L字金具2基",line2:"背の高い大容量機でも前倒れゼロ"}]});default:return null}}function hf(i){switch(i){case"db_glazing_uchannel_blocks":return s({badge:"DB45",stepTag:"EPDM Shore A 80",title:"EPDMグレージングUチャネル ＆ セッティングブロックの強化ガラス保護断面",analogy:"重い強化ガラスをアルミ枠から宙に浮かせて守る、硬めスニーカーの中敷き＆全周ゴム緩衝材",accent:"#0f172a",accentSoft:"#f1f5f9",body:`
